const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
function clone(value){return JSON.parse(JSON.stringify(value))}
function load(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return value||clone(fallback)}catch{return clone(fallback)}}
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state.products));localStorage.setItem('rovan-cart-v3',JSON.stringify(state.cart));localStorage.setItem('rovan-installations-v1',JSON.stringify(state.installations));localStorage.setItem('rovan-customizations-v3',JSON.stringify(state.customizations));localStorage.setItem('rovan-customization-prices-v3',JSON.stringify(state.customizationPrices));localStorage.setItem('rovan-brand-preferences-v1',JSON.stringify(state.brandPreferences));localStorage.setItem('rovan-first-move-v1',JSON.stringify(state.firstMoveChecklist))}
function safe(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
const BRAND_FILTER_CATEGORIES=['cftv','alarmes','portoes','fechaduras','automacao'];
const BRAND_ORDER=['Intelbras','AGL','JFL','Hikvision','HiLook','MDX','iCSee','Deltamovi','Garen','PPA','Contel'];
function inferredBrand(p){
  if(p.brand)return p.brand;
  const text=`${p.name||''} ${p.description||''}`.toLocaleLowerCase('pt-BR');
  return BRAND_ORDER.find(brand=>text.includes(brand.toLocaleLowerCase('pt-BR')))||null;
}
function productBrands(p){return p.brands?.length?p.brands:(inferredBrand(p)?[inferredBrand(p)]:[])}
function categoryBrands(category){
  const found=new Set(state.products.filter(p=>p.active!==false&&p.category===category).flatMap(productBrands));
  return [...found].sort((a,b)=>{const ai=BRAND_ORDER.indexOf(a),bi=BRAND_ORDER.indexOf(b);return (ai<0?999:ai)-(bi<0?999:bi)||a.localeCompare(b,'pt-BR')});
}
function renderBrandFilter(){
  const brands=categoryBrands(state.filter);
  const visible=BRAND_FILTER_CATEGORIES.includes(state.filter)&&brands.length>1;
  $('#brandFilter').hidden=!visible;
  if(!visible){state.brand='todas';$('#brandOptions').innerHTML='';return}
  if(state.brand!=='todas'&&!brands.includes(state.brand))state.brand='todas';
  $('#brandOptions').innerHTML=['todas',...brands].map(brand=>`<button type="button" class="${state.brand===brand?'active':''}" data-brand="${safe(brand)}">${brand==='todas'?'Todas':safe(brand)}</button>`).join('');
  $$('[data-brand]').forEach(button=>button.onclick=()=>{state.brand=button.dataset.brand;renderProducts()});
}
function money(value){return Number(value).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function priceText(value,prefix=''){return value===null||value===undefined?'Sob consulta':`${prefix?`${prefix} `:''}${money(value)}`}
function effectivePrice(p){return state.customizationPrices[p.id]??p.price}
