function firstMoveKey(roomId,itemId){return `${roomId}:${itemId}`}
function firstMoveSelections(){return FIRST_MOVE_ROOMS.map(room=>({room,items:room.items.map(([id,label,qty])=>{const saved=state.firstMoveChecklist[firstMoveKey(room.id,id)];return {id,label,qty:Number(saved?.qty||qty),selected:Boolean(saved?.selected)}}).filter(item=>item.selected&&item.qty>0)})).filter(group=>group.items.length)}
function firstMoveItemCount(){return firstMoveSelections().reduce((sum,group)=>sum+group.items.reduce((n,item)=>n+item.qty,0),0)}
function firstMoveDetailedText(){return firstMoveSelections().map(group=>`${group.room.name}: ${group.items.map(item=>`${item.qty}x ${item.label}`).join(', ')}`).join('\n  ')}
function updateFirstMoveCount(){const count=firstMoveItemCount();$('#firstMoveCount').textContent=`${count} ${count===1?'item selecionado':'itens selecionados'}`}
function renderFirstMove(){
  $('#firstMoveRooms').innerHTML=FIRST_MOVE_ROOMS.map(room=>`<fieldset class="first-move-room"><legend><span>${room.icon}</span>${safe(room.name)}</legend><div>${room.items.map(([id,label,defaultQty])=>{const key=firstMoveKey(room.id,id);const saved=state.firstMoveChecklist[key]||{};return `<label class="first-move-item"><input type="checkbox" data-first-move-check="${safe(key)}" ${saved.selected?'checked':''}><span>${safe(label)}</span><span class="first-move-qty"><button type="button" data-first-move-step="-1" data-first-move-key="${safe(key)}" aria-label="Diminuir quantidade">−</button><input type="number" min="1" max="20" value="${Number(saved.qty||defaultQty)}" data-first-move-qty="${safe(key)}" aria-label="Quantidade de ${safe(label)}"><button type="button" data-first-move-step="1" data-first-move-key="${safe(key)}" aria-label="Aumentar quantidade">+</button></span></label>`}).join('')}</div></fieldset>`).join('');
  $$('[data-first-move-check]').forEach(input=>input.onchange=()=>{const key=input.dataset.firstMoveCheck;state.firstMoveChecklist[key]={...(state.firstMoveChecklist[key]||{}),selected:input.checked,qty:Number($(`[data-first-move-qty="${key}"]`).value)||1};save();updateFirstMoveCount()});
  $$('[data-first-move-qty]').forEach(input=>input.onchange=()=>{const key=input.dataset.firstMoveQty;input.value=Math.max(1,Math.min(20,Number(input.value)||1));state.firstMoveChecklist[key]={...(state.firstMoveChecklist[key]||{}),qty:Number(input.value),selected:$(`[data-first-move-check="${key}"]`).checked};save();updateFirstMoveCount()});
  $$('[data-first-move-step]').forEach(button=>button.onclick=()=>{const input=$(`[data-first-move-qty="${button.dataset.firstMoveKey}"]`);input.value=Math.max(1,Math.min(20,Number(input.value)+Number(button.dataset.firstMoveStep)));input.dispatchEvent(new Event('change'))});
  updateFirstMoveCount();
}
