function productImage(p,cls=''){return p.image?`<img class="${cls}" src="${safe(p.image)}" alt="${safe(p.name)}" loading="lazy" onerror="this.classList.add('image-error')">`:`<span class="image-placeholder">ROVAN</span>`}
function detailBlocks(p){
  const included=p.included?.length?`<ul class="included-list">${p.included.map(x=>`<li>${safe(x)}</li>`).join('')}</ul>`:'';
  const variants=p.variants?.length?`<div class="variant-list">${p.variants.map(x=>`<span>${safe(x)}</span>`).join('')}</div>`:'';
  const placement=p.placement?`<div class="placement-card"><div class="placement-photo placement-${safe(p.placement)}" role="img" aria-label="Exemplo de instalação: ${safe(p.placementLabel)}"></div><span><b>Onde instalar</b>${safe(p.placementLabel)}</span></div>`:'';
  const cftv=p.category==='cftv'&&!p.projectOnly?`<div class="cftv-guide" aria-label="Guia visual de câmeras e imagens"><figure><div class="cftv-scene cftv-dome"></div><figcaption><b>Dome</b>Interior ou área protegida</figcaption></figure><figure><div class="cftv-scene cftv-bullet"></div><figcaption><b>Bullet</b>Exterior e perímetro</figcaption></figure><figure><div class="cftv-scene cftv-day"></div><figcaption><b>Imagem de dia</b>Cores naturais</figcaption></figure><figure><div class="cftv-scene cftv-night cftv-night-bw"></div><figcaption><b>Noite infravermelha</b>Preto e branco nos modelos comuns</figcaption></figure><figure><div class="cftv-scene cftv-night"></div><figcaption><b>Noite Full Color</b>Cor com iluminação mínima ou auxiliar</figcaption></figure></div>`:'';
  return `${included}${variants}${placement}${cftv}`;
}
