function installationValue(i){return i.valueText||(i.price===0?'Sem custo':i.price?`A partir de ${money(i.price)}`:'Sob medida')}
function renderProducts(){
  const hasSelection=Boolean(state.filter);
  $('#catalogResults').hidden=!hasSelection;
  $('#catalogSearch').hidden=!hasSelection;
  $('#catalogInstruction').hidden=hasSelection;
  if(!hasSelection){$('#brandFilter').hidden=true;$('#productGrid').innerHTML='';$('#catalogCount').textContent='';return}
  renderCategoryTip();
  renderBrandFilter();
  const q=state.query.trim().toLocaleLowerCase('pt-BR');
  const products=state.products.filter(p=>{
    if(p.active===false||p.category!==state.filter)return false;
    if(!(`${p.name} ${p.description||''}`).toLocaleLowerCase('pt-BR').includes(q))return false;
    const brands=productBrands(p);
    return state.brand==='todas'||brands.length===0||brands.includes(state.brand);
  });
  $('#selectedCategoryName').textContent=CATEGORY_NAMES[state.filter]||state.filter;
  $('#catalogCount').textContent=`${products.length} ${products.length===1?'produto':'produtos'}`;
  $('#productGrid').innerHTML=products.map(p=>{
    const brands=productBrands(p);
    const selectedBrand=state.brand!=='todas'&&brands.includes(state.brand)?state.brand:(brands.length===1?brands[0]:null);
    const brandLabel=selectedBrand?`<span class="chosen-brand">Marca: ${safe(selectedBrand)}</span>`:(brands.length>1?'<span class="chosen-brand neutral">Marca escolhida depois</span>':'');
    const visualTag=p.id.startsWith('motor-basculante')?'<span class="product-tag">Referência visual PPA</span>':p.source==='Kyte'?'<span class="product-tag">Catálogo atual</span>':p.projectOnly?'<span class="product-tag">Sob medida</span>':'';
    const chooseLabel=p.id==='kit-primeira-mudanca'?'Montar lista por ambiente':'Escolher produto';
    const installHint=p.id==='kit-primeira-mudanca'?'Você escolhe os itens e a instalação na próxima etapa.':'Instalação opcional — o valor aparece na próxima etapa.';
    return `<article class="product ${p.customizable?'product-featured':''}" data-category="${safe(p.category)}"><div class="product-visual">${productImage(p)}${visualTag}</div><div class="product-info"><span class="product-category">${safe(CATEGORY_NAMES[p.category]||p.category)}</span>${brandLabel}<h3>${safe(p.name)}</h3>${p.description?`<p>${safe(p.description)}</p>`:'<p class="description-pending">Escolha o produto e consulte a instalação com a ROVAN.</p>'}${detailBlocks(p)}${p.customizable?`<button class="customize-product" type="button" data-customize="${safe(p.id)}">Personalizar este kit</button>`:''}${p.projectOnly?'<button class="customize-product" type="button" data-open-survey>Iniciar pré-vistoria com fotos</button>':''}<div class="product-bottom"><div class="product-price"><small>${p.pricePrefix?'PREÇO-BASE DO PRODUTO':'VALOR DO PRODUTO'}</small><strong>${priceText(p.price,p.pricePrefix)}</strong></div>${p.projectOnly?'':`<button class="add-product" type="button" data-add="${safe(p.id)}">${chooseLabel}</button>`}</div>${p.projectOnly?'':`<small class="installation-optional">${installHint}</small>`}</div></article>`;
  }).join('');
  $('#emptyState').hidden=products.length>0;$$('[data-add]').forEach(b=>b.onclick=()=>chooseProduct(b.dataset.add));$$('[data-customize]').forEach(b=>b.onclick=()=>openCustomizer(b.dataset.customize));$$('[data-open-survey]').forEach(b=>b.onclick=()=>openLayer($('#surveyModal')));
}
function chooseProduct(id){const p=state.products.find(x=>x.id===id);if(!p)return;if(id==='kit-primeira-mudanca'){openFirstMove();return}const brands=productBrands(p);const chosen=state.brand!=='todas'&&brands.includes(state.brand)?state.brand:(brands.length===1?brands[0]:null);if(chosen)state.brandPreferences[id]=chosen;else delete state.brandPreferences[id];save();const i=installationProfile(p);if(i.price===0){addToCart(id,false);toast('Produto adicionado — este item não precisa de instalação');return}openInstallation(id)}
function addToCart(id,wantsInstallation=false){const p=state.products.find(x=>x.id===id);if(!p)return;state.cart[id]=(state.cart[id]||0)+1;if(wantsInstallation)state.installations[id]=true;else if(!state.installations[id])state.installations[id]=false;save();renderCart()}
function changeQty(id,delta){const next=(state.cart[id]||0)+delta;if(next<=0){delete state.cart[id];delete state.installations[id];delete state.brandPreferences[id]}else state.cart[id]=next;save();renderCart()}
function renderCart(){const entries=Object.entries(state.cart).filter(([id])=>state.products.some(p=>p.id===id));$('#cartItems').innerHTML=entries.map(([id,qty])=>{const p=state.products.find(x=>x.id===id);const custom=state.customizations[id];const install=state.installations[id];const brand=state.brandPreferences[id];const i=installationProfile(p);const editList=id==='kit-primeira-mudanca'?'<button class="cart-edit-list" type="button" data-edit-first-move>Editar lista por ambiente</button>':'';return `<div class="cart-item"><div class="cart-item-icon">${productImage(p,'cart-thumb')}</div><div><h4>${safe(p.name)}</h4><small>Produto: ${priceText(effectivePrice(p),p.variantPrices&&custom?'':p.pricePrefix)}</small>${brand?`<em>Marca: ${safe(brand)}</em>`:''}${custom?`<em>${safe(custom)}</em>`:''}${editList}<em class="cart-installation ${install?'selected':''}">${install?`Instalação solicitada · ${safe(installationValue(i))}`:'Somente o produto'}</em></div><div class="qty"><button data-qty="${safe(id)}" data-delta="-1">−</button><span>${qty}</span><button data-qty="${safe(id)}" data-delta="1">+</button></div></div>`}).join('');const total=entries.reduce((sum,[id,qty])=>{const p=state.products.find(x=>x.id===id);return sum+(effectivePrice(p)||0)*qty},0);const hasQuote=entries.some(([id])=>state.products.find(p=>p.id===id)?.price==null);const hasBase=entries.some(([id])=>{const p=state.products.find(x=>x.id===id);return p?.pricePrefix&&!state.customizationPrices[id]});$('#cartTotal').textContent=hasQuote?(total?`${money(total)} + itens sob consulta`:'Sob consulta'):hasBase?`A partir de ${money(total)}`:money(total);$('#cartCount').textContent=entries.reduce((n,[,q])=>n+q,0);$('#cartEmpty').hidden=entries.length>0;$('#cartSummary').hidden=entries.length===0;$$('[data-qty]').forEach(b=>b.onclick=()=>changeQty(b.dataset.qty,Number(b.dataset.delta)));$$('[data-edit-first-move]').forEach(b=>b.onclick=()=>{closeLayers();openFirstMove()})}
function openLayer(el){el.classList.add('open');el.setAttribute('aria-hidden','false');$('#overlay').classList.add('show');document.body.style.overflow='hidden'}
function closeLayers(){$$('.open').forEach(x=>x.classList.remove('open'));$$('[aria-hidden="false"]').forEach(x=>x.setAttribute('aria-hidden','true'));$('#overlay').classList.remove('show');document.body.style.overflow=''}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
function filterTo(category){state.filter=category;state.brand='todas';state.query='';$('#searchInput').value='';$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===category));renderProducts();$('#catalogo').scrollIntoView({behavior:'smooth'})}
function closeCatalogLine(){state.filter=null;state.brand='todas';state.query='';$('#searchInput').value='';$$('[data-filter]').forEach(b=>b.classList.remove('active'));renderProducts();$('#catalogo').scrollIntoView({behavior:'smooth'})}
function openInstallation(id){
  const p=state.products.find(x=>x.id===id);if(!p)return;const i=installationProfile(p);state.installationProductId=id;
  $('#installationProductImage').innerHTML=productImage(p);
  $('#installationProductName').textContent=state.brandPreferences[id]?`${p.name} · ${state.brandPreferences[id]}`:p.name;
  const productPrice=priceText(effectivePrice(p),p.variantPrices&&state.customizations[id]?'':p.pricePrefix);
  $('#installationProductPrice').textContent=productPrice;
  $('#installationProductPriceRepeat').textContent=productPrice;
  $('#installationLaborPriceRepeat').textContent=installationValue(i);
  $('#installationEstimateLabel').textContent=i.label;
  $('#installationEstimateValue').textContent=installationValue(i);
  $('#installationEstimateUnit').textContent=i.unit;
  $('#installationIncluded').innerHTML=i.included.map(x=>`<li>${safe(x)}</li>`).join('');
  $('#installationConditions').textContent=i.conditions;
  $('#installationReference').textContent=i.reference;
  $('#installationAdd').textContent=p.projectOnly?'Solicitar análise deste projeto':'Adicionar produto + solicitar instalação';
  $('#installationQuestion').hidden=false;
  $('#installationReveal').hidden=true;
  openLayer($('#installationModal'));
}
function openCustomizer(id){
  const p=state.products.find(x=>x.id===id);if(!p)return;
  const brands=productBrands(p);const chosen=state.brand!=='todas'&&brands.includes(state.brand)?state.brand:(brands.length===1?brands[0]:null);if(chosen)state.brandPreferences[id]=chosen;else delete state.brandPreferences[id];save();
  const form=$('#customizeForm');form.reset();form.elements.productId.value=id;
  $('#customizeTitle').textContent=`Personalizar: ${p.name}`;
  const isCftv=p.customType==='cftv';$('#alarmCustomizeFields').hidden=isCftv;$('#cftvCustomizeFields').hidden=!isCftv;
  $('#sensorConnectionField').hidden=!['alarme-kit-anm24','alarme-kit-amt1000'].includes(p.id);
  if(!isCftv)$('#alarmIncludedNote').textContent=['alarme-kit-anm24','alarme-kit-amt1000','alarme-kit-amt8000'].includes(p.id)?'O kit considera sirene, bateria e controle adicional. ANM 24 NET e AMT 1000 SMART aceitam sensores com fio e sem fio; a linha AMT 8000 utiliza dispositivos sem fio da família 8000.':'Este kit utiliza somente sensores sem fio. Sensores, controles, sirene e alimentação auxiliar são confirmados conforme o modelo e a necessidade do local.';
  if(isCftv){const total=p.id==='cftv-kit-8'?8:4;form.elements.domeCameras.max=total;form.elements.bulletCameras.max=total;form.elements.domeCameras.value=Math.ceil(total/2);form.elements.bulletCameras.value=Math.floor(total/2)}
  openLayer($('#customizeModal'));
}
function renderAdmin(){
  $('#adminCount').textContent=`${state.products.length} produtos cadastrados`;
  $('#adminList').innerHTML=state.products.map(p=>`<div class="admin-product ${p.active===false?'inactive':''}"><div class="admin-thumb">${productImage(p)}</div><div><strong>${safe(p.name)}</strong><small>${priceText(p.price,p.pricePrefix)} · ${safe(CATEGORY_NAMES[p.category]||p.category)}</small></div><button type="button" data-edit="${safe(p.id)}">Editar</button><button type="button" data-toggle="${safe(p.id)}">${p.active===false?'Ativar':'Ocultar'}</button></div>`).join('');
  $$('[data-edit]').forEach(b=>b.onclick=()=>editProduct(b.dataset.edit));$$('[data-toggle]').forEach(b=>b.onclick=()=>toggleProduct(b.dataset.toggle));
}
function resetForm(){state.editingId=null;$('#productForm').reset();$('#editingId').value='';$('#formTitle').textContent='Adicionar produto';$('#saveProduct').textContent='Adicionar produto';$('#cancelEdit').hidden=true;$('#deleteProduct').hidden=true}
function editProduct(id){const p=state.products.find(x=>x.id===id);if(!p)return;state.editingId=id;const f=$('#productForm');f.elements.name.value=p.name;f.elements.price.value=p.price==null?'':String(p.price).replace('.',',');f.elements.category.value=p.category;f.elements.image.value=p.image||'';f.elements.description.value=p.description||'';$('#editingId').value=id;$('#formTitle').textContent='Editar produto';$('#saveProduct').textContent='Salvar alterações';$('#cancelEdit').hidden=false;$('#deleteProduct').hidden=false;f.scrollIntoView({behavior:'smooth',block:'start'})}
function toggleProduct(id){const p=state.products.find(x=>x.id===id);if(!p)return;p.active=p.active===false;save();renderProducts();renderAdmin()}
async function imageFromForm(form){const file=form.elements.imageFile.files[0];if(!file)return form.elements.image.value.trim();if(file.size>900000)throw new Error('Escolha uma imagem menor que 900 KB');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}

