$('#customizeForm').onsubmit=e=>{e.preventDefault();const f=e.target;const id=f.elements.productId.value;const p=state.products.find(x=>x.id===id);if(!p)return;let summary;if(p.customType==='cftv'){const tech=f.elements.cftvTechnology.value;const dome=Number(f.elements.domeCameras.value);const bullet=Number(f.elements.bulletCameras.value);const total=p.id==='cftv-kit-8'?8:4;if(dome+bullet!==total){toast(`Escolha ao todo ${total} câmeras dome e bullet`);return}const night=tech==='Analógico 2 MP Full Color'?'visão noturna colorida':tech==='Analógico 1 MP'?'visão noturna infravermelha em preto e branco':'visão noturna definida conforme o modelo IP';summary=`${tech}; ${dome} dome; ${bullet} bullet; HD 500 GB; ${night}`;state.customizationPrices[id]=p.variantPrices?.[tech]??p.price}else{const acceptsWired=['alarme-kit-anm24','alarme-kit-amt1000'].includes(p.id);const connection=acceptsWired?f.elements.sensorConnection.value:p.id==='alarme-kit-amt8000'?'Sem fio - linha 8000':'Sem fio';summary=`${connection}; ${f.elements.openingSensors.value} abertura; ${f.elements.internalSensors.value} internos PET; ${f.elements.externalSensors.value} externos; ${f.elements.extraRemotes.value} controle(s) adicional(is); sirene e bateria conforme o kit`;delete state.customizationPrices[id]}state.customizations[id]=summary;save();closeLayers();openInstallation(id);toast('Configuração pronta. Agora escolha se deseja instalação.')};
$('#surveyForm').onsubmit=e=>{e.preventDefault();const f=e.target;const fileFields=['photosOverview','photosCeiling','photosRouter','photosPower','photosRoute','photosGround'];const photoCount=fileFields.reduce((n,key)=>n+(f.elements[key]?.files?.length||0),0);const lines=[`Local: ${f.elements.city.value} — ${f.elements.neighborhood.value}`,`Tipo: ${f.elements.projectType.value}`,`Imóvel: ${f.elements.propertyType.value}`,`Forro/telhado: ${f.elements.ceilingAccess.value}`,`Passagem da fiação: ${f.elements.wiringRoute.value}`,`Piso no trajeto: ${f.elements.floorWork.value}`,`Energia: ${f.elements.power.value}`,`Roteador/sinal: ${f.elements.router.value||'não informado'}`,`Observações: ${f.elements.notes.value||'não informado'}`,`Fotos selecionadas para anexar: ${photoCount}`];$('#surveySummary').value=`Olá, ROVAN! Quero solicitar uma solução personalizada.\n\nPRÉ-VISTORIA\n${lines.join('\n')}\n\nVou anexar as fotos que considero necessárias. Podem me orientar sobre os próximos passos?`;$('#surveyResult').hidden=false;$('#surveyResult').scrollIntoView({behavior:'smooth',block:'nearest'});toast('Resumo preparado para sua revisão')};
