$('#checkoutButton').onclick=()=>{const entries=Object.entries(state.cart);if(!entries.length)return;const name=$('#customerName').value.trim();const phone=$('#customerPhone').value.trim();const address=$('#serviceAddress').value.trim();const reference=$('#serviceReference').value.trim();const rawDate=$('#preferredDate').value;const period=$('#preferredPeriod').value;if(!name){toast('Informe seu nome para continuar');$('#customerName').focus();return}if(!phone){toast('Informe um telefone para contato');$('#customerPhone').focus();return}if(!address){toast('Informe o endereço completo');$('#serviceAddress').focus();return}const lines=entries.map(([id,qty])=>{const p=state.products.find(x=>x.id===id);const brand=state.brandPreferences[id]?`\n  Marca: ${state.brandPreferences[id]}`:'';const custom=state.customizations[id]?`\n  Configuração: ${state.customizations[id]}`:'';const i=installationProfile(p);const install=state.installations[id]?`\n  Instalação: SIM — ${installationValue(i)} (${i.unit})`:'\n  Instalação: NÃO — somente o produto';return `• ${qty}x ${p.name}\n  Produto: ${priceText(effectivePrice(p),p.pricePrefix)}${brand}${install}${custom}`});const total=entries.reduce((sum,[id,qty])=>{const p=state.products.find(p=>p.id===id);return sum+(p?(effectivePrice(p)||0)*qty:0)},0);const hasQuote=entries.some(([id])=>{const p=state.products.find(p=>p.id===id);return p&&effectivePrice(p)==null});const hasBase=entries.some(([id])=>state.products.find(p=>p.id===id)?.pricePrefix);const subtotal=hasQuote?(total?`${money(total)} + itens sob consulta`:'Sob consulta'):hasBase?`A partir de ${money(total)}`:money(total);const payment=$('#paymentPreference').value;const preferredDate=rawDate?new Date(`${rawDate}T12:00:00`).toLocaleDateString('pt-BR'):'a combinar';const customer=`Nome: ${name}\nTelefone: ${phone}\nEndereço: ${address}${reference?`\nComplemento/referência: ${reference}`:''}\nPreferência de atendimento: ${preferredDate} — ${period}`;const msg=`Olá, ROVAN! Meu nome é ${name} e gostaria de confirmar este pedido.\n\nDADOS DO CLIENTE\n${customer}\n\nITENS DO PEDIDO\n${lines.join('\n\n')}\n\nSubtotal dos produtos: ${subtotal}\nA mão de obra está indicada separadamente em cada item.\nPreferência de pagamento: ${payment}\n\nEntendi que este pedido ainda não é uma cobrança e que a data será confirmada. Podem confirmar disponibilidade, materiais, mão de obra, prazo e condições de pagamento?`;window.open(`https://wa.me/${ROVAN_WHATSAPP}?text=${encodeURIComponent(msg)}`,'_blank')};
$('#productForm').onsubmit=async e=>{e.preventDefault();const f=e.target;try{const name=f.elements.name.value.trim();const raw=f.elements.price.value.trim().replace('.','').replace(',','.');const image=await imageFromForm(f);const existing=state.products.find(p=>p.id===state.editingId);const product={id:existing?.id||`produto-${Date.now()}`,name,price:raw?Number(raw):null,category:f.elements.category.value,image,description:f.elements.description.value.trim(),active:existing?.active!==false,source:existing?.source||'ROVAN'};if(existing)Object.assign(existing,product);else state.products.unshift(product);save();renderProducts();renderAdmin();resetForm();toast(existing?'Produto atualizado':'Produto adicionado')}catch(error){toast(error.message||'Não foi possível salvar')}};
